/**
 * NamingOrgan — the SINTER×Elixis integration. Elixis (revived engine, GLM
 * seat) names what sinter births: every domain-best champion and every Glass
 * Bead move receives a PLATE (silk + name + subtitle) generated by the
 * Elixis game engine and gated by its machine-encoded discipline
 * (prosody rubric, kill lists, deniability) — one implementation of the
 * laws, two substrates.
 *
 * Bounded: ≤2 Elixis calls per wave (one naming, one semantic thread
 * confirmation). Graceful skip when the service is unreachable — the organ
 * is never fatal to the wave. State: .omx/atelier/game/plates.json (atomic).
 */

import { readFileSync, mkdirSync, existsSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { join } from 'node:path';
import { writeAtomicSync } from '../shared/fsAtomic.js';

export interface Plate {
  silk: string;
  name: string;
  subtitle: string;
  partner?: string;
  prosody?: Record<string, number>;
  deniability?: unknown;
  discipline_pass?: boolean;
}

export interface PlateEntry {
  key: string;
  kind: 'best' | 'move';
  domain: string;
  /** Every domain the named work spans, primary FIRST (law 30). Champion
   *  plates carry one; move plates carry the move's two bead domains. */
  domains: string[];
  plate: Plate;
  at: string;
}

/** Plate domain shaping (exported for unit tests): champions are single-domain;
 *  moves inherit the thread's two bead domains, primary (domainA) first. */
export function plateDomainsFor(kind: 'best' | 'move', domain: string, thread?: { domainA: string; domainB: string }): string[] {
  return kind === 'move' && thread ? [thread.domainA, thread.domainB] : [domain];
}

type FetchLike = (url: string, init?: { method?: string; headers?: Record<string, string>; body?: string; signal?: AbortSignal }) => Promise<{ ok: boolean; json(): Promise<unknown> }>;

const DEFAULT_GAME_URL = 'http://localhost:3110/api/game';
const DEFAULT_NAMING_URL = 'http://localhost:3110/api/naming';

function elixisUrl(): string {
  return process.env.ELIXIS_URL || DEFAULT_GAME_URL;
}

function namingUrl(): string {
  return process.env.ELIXIS_NAMING_URL || DEFAULT_NAMING_URL;
}

function loadPlates(cwd: string): PlateEntry[] {
  const p = join(cwd, '.omx', 'atelier', 'game', 'plates.json');
  try {
    return JSON.parse(readFileSync(p, 'utf8')) as PlateEntry[];
  } catch {
    return [];
  }
}

interface GameOutcome {
  threads?: Array<{ isomorphic?: boolean }>;
  cross_domain_thread_count?: number;
  tensions?: unknown[];
}

async function postJson(url: string, body: unknown, fetchImpl: FetchLike, timeoutMs = 150000): Promise<unknown | null> {
  try {
    const res = await fetchImpl(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(timeoutMs),
    });
    if (!res.ok) return null;
    return await res.json();
  } catch {
    return null; // service down / timeout — graceful skip, never fatal
  }
}

/** Execute Elixis's own discipline module on a candidate (single implementation
 *  of the laws — sinter runs their code, never reimplements it). */
export function disciplineCheck(names: string[]): { pass: Record<string, boolean> } | null {
  const home = process.env.ELIXIS_HOME ?? join(process.env.HOME || '', 'workspaces', 'kyanite-labs', 'Elixis');
  if (!existsSync(join(home, 'elixis', 'discipline.py'))) return null; // repo absent — skip check
  try {
    
    const script = 'import sys,json;sys.path.insert(0,"' + home + '");from elixis.discipline import kill_list_violations;print(json.dumps({n: len(kill_list_violations(n))==0 for n in json.loads(sys.argv[1])}))';
    const out = execFileSync('python3', ['-c', script, JSON.stringify(names)], { timeout: 30000 }).toString();
    return { pass: JSON.parse(out.trim()) };
  } catch {
    return null;
  }
}

/** Name unnamed domain-best champions and the latest unnamed game move. */
export async function nameChampions(
  cwd: string,
  options: { fetchImpl?: FetchLike; maxPerWave?: number } = {},
): Promise<{ named: PlateEntry[]; skipped: string; elixisUp: boolean }> {
  const fetchImpl = options.fetchImpl ?? (globalThis.fetch as unknown as FetchLike);
  const maxPerWave = options.maxPerWave ?? 2;
  const plates = loadPlates(cwd);
  const plated = new Set(plates.map(e => e.key));

  interface Target { key: string; kind: 'best' | 'move'; domain: string; domains: string[]; seed: string; silk: string; brain: string }
  const targets: Target[] = [];

  // domain-bests without plates
  try {
    const bests = JSON.parse(readFileSync(join(cwd, '.omx', 'atelier', 'best-per-domain.json'), 'utf8')) as Record<string, { dir?: string; mean?: number }>;
    for (const [domain, entry] of Object.entries(bests)) {
      const key = `best:${domain}`;
      if (plated.has(key) || !entry?.dir) continue;
      let prompt = '';
      try {
        prompt = readFileSync(join(entry.dir, 'prompt.txt'), 'utf8').slice(0, 160);
      } catch { /* optional */ }
      const seedWord = (prompt.split(/\s+/).filter(w => w.length > 3)[Math.min(1, Math.max(0, prompt.split(/\s+/).length - 1))] || domain);
      targets.push({
        key, kind: 'best', domain, domains: plateDomainsFor('best', domain),
        seed: seedWord.toLowerCase().replace(/[^a-z]/g, '') || domain,
        silk: `${domain.toUpperCase()} · CRAFT ${Number(entry.mean ?? 0).toFixed(1)} · RECEIPTS`,
        brain: `An artwork champion in the ${domain} domain of a generative-art system. Receipts: judged mean ${Number(entry.mean ?? 0).toFixed(2)} of 5. Prompt intent: ${prompt || `a ${domain} composition`}.`,
      });
    }
  } catch { /* no bests file — skip */ }

  // the latest unnamed move
  try {
    const moves = JSON.parse(readFileSync(join(cwd, '.omx', 'atelier', 'game', 'moves.json'), 'utf8')) as Array<{ at: string; kind: string; thread: { domainA: string; domainB: string; similarity: number } }>;
    const last = moves[moves.length - 1];
    if (last) {
      const key = `move:${last.at}`;
      if (!plated.has(key)) {
        targets.push({
          key, kind: 'move', domain: `${last.thread.domainA}x${last.thread.domainB}`,
          domains: plateDomainsFor('move', `${last.thread.domainA}x${last.thread.domainB}`, last.thread),
          seed: `${last.thread.domainA}${last.thread.domainB}`.slice(0, 14),
          silk: `${last.thread.domainA.toUpperCase()} x ${last.thread.domainB.toUpperCase()} · ISO ${last.thread.similarity.toFixed(3)}`,
          brain: `A Glass Bead Game move pairing a ${last.thread.domainA} artwork with a ${last.thread.domainB} artwork found structurally isomorphic.`,
        });
      }
    }
  } catch { /* no moves yet */ }

  const batch = targets.slice(0, maxPerWave);
  if (batch.length === 0) return { named: [], skipped: 'nothing to name', elixisUp: true };

  const named: PlateEntry[] = [];
  let elixisUp = true;
  for (const target of batch) {
    const report = await postJson(namingUrl(), { name: target.seed, context: target.brain, generate_variants: true }, fetchImpl) as
      { variants?: Array<{ name: string; availability_score?: number; reasoning?: string }> } | null;
    if (report === null) { elixisUp = false; break; }
    const engineVariants = report.variants ?? [];
    if (engineVariants.length === 0) continue; // engine declined — no plate on vibes
    const variants = [...engineVariants, { name: target.seed, availability_score: 0.5, reasoning: '' }]
      .sort((a, b) => (b.availability_score ?? 0) - (a.availability_score ?? 0));
    const discipline = disciplineCheck(variants.map(v => v.name));
    const chosen = variants.find(v => !discipline || discipline.pass[v.name]) ?? null;
    if (!chosen) continue; // every candidate killed by the discipline — correct stinginess
    const plate: Plate = {
      name: chosen.name,
      silk: target.silk,
      subtitle: (chosen.reasoning ?? '').slice(0, 120),
      discipline_pass: true,
    };
    named.push({ key: target.key, kind: target.kind, domain: target.domain, domains: target.domains, plate, at: new Date().toISOString() });
    plates.push(named[named.length - 1]);
  }

  mkdirSync(join(cwd, '.omx', 'atelier', 'game'), { recursive: true });
  writeAtomicSync(join(cwd, '.omx', 'atelier', 'game', 'plates.json'), JSON.stringify(plates, null, 1));
  return { named, skipped: elixisUp ? 'engine declined remaining candidates' : 'elixis unreachable', elixisUp };
}

/**
 * ThreadFinder v2 — semantic confirmation of the latest move's top thread by
 * the Elixis engine: both artifacts' source excerpts enter one game; the
 * move record gains `semantic` (threads + tensions the engine drew between
 * them). One call per wave, bounded; skip keeps the move cosine-only.
 */
export async function confirmThreadSemantically(
  cwd: string,
  options: { fetchImpl?: FetchLike } = {},
): Promise<{ confirmed: boolean; threads: number; tensions: number } | null> {
  const fetchImpl = options.fetchImpl ?? (globalThis.fetch as unknown as FetchLike);
  const movesPath = join(cwd, '.omx', 'atelier', 'game', 'moves.json');
  const beadsPath = join(cwd, '.omx', 'atelier', 'game', 'beads.json');
  if (!existsSync(movesPath) || !existsSync(beadsPath)) return null;
  const moves = JSON.parse(readFileSync(movesPath, 'utf8')) as Array<Record<string, unknown>>;
  const beads = new Map((JSON.parse(readFileSync(beadsPath, 'utf8')) as Array<{ id: string; dir: string; domain: string }>).map(b => [b.id, b]));
  const last = moves[moves.length - 1];
  if (!last || last.semantic) return null; // already confirmed or nothing to confirm
  const thread = last.thread as { a: string; b: string };
  const beadA = beads.get(thread.a);
  const beadB = beads.get(thread.b);
  if (!beadA || !beadB) return null;

  let excerptA = '', excerptB = '';
  try {
    excerptA = readFileSync(join(beadA.dir, 'source.txt'), 'utf8').slice(0, 500);
    excerptB = readFileSync(join(beadB.dir, 'source.txt'), 'utf8').slice(0, 500);
  } catch { return null; }

  const game = await postJson(elixisUrl(), { brain_dump: `Two artworks from different domains judged structurally isomorphic. A (${beadA.domain}): ${excerptA}\n\nB (${beadB.domain}): ${excerptB}\n\nFind the structural bridges between A and B.` }, fetchImpl) as GameOutcome | null;
  if (game === null) return null;
  const isomorphic = Array.isArray(game.threads) ? game.threads.filter(t => t.isomorphic === true).length : 0;
  const crossDomain = game.cross_domain_thread_count ?? 0;
  const threads = isomorphic + crossDomain;
  const tensions = Array.isArray(game.tensions) ? game.tensions.length : 0;
  const confirmed = threads > 0;
  last.semantic = { confirmed, threads, tensions, at: new Date().toISOString() };
  writeAtomicSync(movesPath, JSON.stringify(moves, null, 1));
  return { confirmed, threads, tensions };
}
